package net.civeira.phylax.common.security;

import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Optional;

import net.civeira.phylax.common.exception.StepUpRequiredException;

public interface Actor {
  String getUid();

  String getTenant();

  String getName();

  boolean isAuthenticated();

  List<String> getRoles();

  List<String> getGroups();

  List<String> getScopes();

  /**
   * Whether the token was issued after a login with a second factor ({@code amr} with {@code mfa}).
   */
  boolean isMfa();

  /**
   * Moment of the real login ({@code auth_time}), empty when the token does not say it.
   */
  Optional<Instant> getAuthenticatedAt();

  /**
   * Whether the login used a second factor.
   *
   * @return true when the token carries the multi factor level
   */
  default boolean hasMfa() {
    return isAuthenticated() && isMfa();
  }

  /**
   * Whether the login used a second factor no older than the given age.
   *
   * @param maxAge maximum age of the login
   * @return true when the token carries the multi factor level and a recent enough
   *         {@code auth_time}
   */
  default boolean hasMfa(Duration maxAge) {
    return hasMfa()
        && getAuthenticatedAt().map(at -> !at.plus(maxAge).isBefore(Instant.now())).orElse(false);
  }

  /**
   * Demands a login with a second factor.
   *
   * @throws StepUpRequiredException when the token lacks it, so the client asks for it
   */
  default void requireMfa() {
    if (!hasMfa()) {
      throw new StepUpRequiredException("A second authentication factor is required");
    }
  }

  /**
   * Demands a login with a second factor no older than the given age.
   *
   * @param maxAge maximum age of the login
   * @throws StepUpRequiredException when the token lacks it or it is too old, so the client asks
   *         for a new one
   */
  default void requireMfa(Duration maxAge) {
    if (!hasMfa(maxAge)) {
      throw new StepUpRequiredException("A recent second authentication factor is required",
          maxAge);
    }
  }

  default boolean isIdentifiedAs(String u) {
    return getUid().equals(u);
  }

  default boolean isInGroup(String group) {
    if (group.endsWith(":*")) {
      String prefix = group.substring(0, group.length() - 1);
      return getGroups().stream().anyMatch(has -> has.startsWith(prefix));
    } else {
      return getGroups().contains(group);
    }
  }

  default boolean isInAnyGroup(String... groups) {
    for (String group : groups) {
      if (isInGroup(group)) {
        return true;
      }
    }
    return false;
  }

  default boolean hasScope(String scope) {
    if (scope.endsWith(":*")) {
      String prefix = scope.substring(0, scope.length() - 1);
      return getScopes().stream().anyMatch(has -> has.startsWith(prefix));
    } else {
      return getScopes().contains(scope);
    }

  }

  default boolean hasAnyScope(String... scopes) {
    for (String scope : scopes) {
      if (hasScope(scope)) {
        return true;
      }
    }
    return false;
  }

  default boolean hasRole(String role) {
    if (role.endsWith(":*")) {
      String prefix = role.substring(0, role.length() - 1);
      return getRoles().stream().anyMatch(has -> has.startsWith(prefix));
    } else {
      return getRoles().contains(role);
    }

  }

  default boolean hasAnyRole(String... roles) {
    for (String role : roles) {
      if (hasRole(role)) {
        return true;
      }
    }
    return false;
  }
}
